<div class="page-heading"><div><span class="eyebrow text-primary">ROLE-BASED ACCESS CONTROL</span><h2>Role และ Permission</h2><p>ทุก route และ action ตรวจ Permission ทางฝั่งเซิร์ฟเวอร์</p></div></div>
<div class="row g-4"><?php foreach($roles as $role): ?><div class="col-12 col-xl-6"><section class="panel h-100"><div class="panel-header"><div><h3><?= e($role['name']) ?></h3><p><?= e($role['description']) ?></p></div><span class="role-badge"><?= e($role['slug']) ?></span></div><form method="post" action="<?= e(url('/admin/roles/'.$role['id'])) ?>"><?= csrf_field() ?><div class="permission-grid"><?php foreach($permissions as $permission): ?><label class="permission-item"><input class="form-check-input" type="checkbox" name="permissions[]" value="<?= (int)$permission['id'] ?>" <?= in_array((int)$permission['id'],$role['permission_ids'],true)?'checked':'' ?> <?= $role['slug']==='admin'?'disabled':'' ?>><span><strong><?= e($permission['name']) ?></strong><small><?= e($permission['slug']) ?></small></span></label><?php endforeach; ?></div><?php if($role['slug']!=='admin'): ?><button class="btn btn-primary mt-4" type="submit"><i class="fa-solid fa-floppy-disk me-2"></i>บันทึก Permission</button><?php else: ?><p class="alert alert-light mt-4 mb-0"><i class="fa-solid fa-shield-halved me-2"></i>Admin มีสิทธิ์ทั้งหมดโดยอัตโนมัติ</p><?php endif; ?></form></section></div><?php endforeach; ?></div>

